import{_ as e,o as t,c as d,a2 as n}from"./chunks/framework.DtFGJNng.js";const m=JSON.parse('{"title":"Masalah umum","description":"","frontmatter":{},"headers":[],"relativePath":"masalah-umum.md","filePath":"masalah-umum.md","lastUpdated":1794532423000}'),o={name:"masalah-umum.md"};function i(s,a,r,c,u,l){return t(),d("div",null,[...a[0]||(a[0]=[n('<h1 id="masalah-umum" tabindex="-1">Masalah umum <a class="header-anchor" href="#masalah-umum" aria-label="Permalink to &quot;Masalah umum&quot;">​</a></h1><p>Saat CLI menolak sesuatu, ia tidak menulis apa pun dan menampilkan semua alasannya sekaligus. Kode keluarnya <code>1</code>. Berikut pesan yang paling sering muncul, beserta artinya.</p><h2 id="saat-konfirmasi-deuz-ready" tabindex="-1">Saat konfirmasi (<code>deuz ready</code>) <a class="header-anchor" href="#saat-konfirmasi-deuz-ready" aria-label="Permalink to &quot;Saat konfirmasi (`deuz ready`)&quot;">​</a></h2><p><strong><code>&lt;artifact&gt; is incomplete: missing &lt;file&gt;</code></strong> File dokumennya belum ada. Untuk specs, setiap capability di proposal butuh <code>specs/&lt;capability&gt;/spec.md</code>. Tulis dulu lewat <code>/deuz:continue</code>.</p><p><strong><code>&lt;artifact&gt; is locked: &lt;lainnya&gt; not ready</code></strong> Dokumen yang dibutuhkan belum <code>ready</code>. Lihat siapa yang ditunggu dengan <code>/deuz:status</code>.</p><p><strong><code>&lt;peran&gt; is not an owner of &lt;artifact&gt; (owners: …)</code></strong> Peran itu bukan pemilik dokumen ini. Contoh: <code>qa is not an owner of proposal (owners: analyst, business)</code>. Periksa juga bahwa peran itu aktif di <code>config.yaml</code>.</p><p><strong><code>Type is missing (one of feature, enhancement, bug, tech, chore)</code></strong> Project memakai gate bisnis, jadi proposal wajib punya baris <code>| Type | … |</code>. Kalau nilainya ada tapi tidak dikenal, pesannya <code>Type &quot;&lt;nilai&gt;&quot; is unknown</code>.</p><p><strong><code>a feature needs business approval: tick business in the affected areas</code></strong> Fitur selalu melewati Gate 1. Centang <code>- [x] business</code> di proposal.</p><p><strong><code>record the business-impact triage on a &quot;Triage:&quot; line</code></strong><code>bug</code> atau <code>enhancement</code> yang tidak mencentang <code>business</code> harus mencatat hasil triage, misalnya <code>Triage: tidak ada dampak bisnis, dibahas dengan analyst pada 2026-11-12</code>.</p><p><strong><code>open blocking questions: …</code></strong> Bisnis tidak bisa mengonfirmasi selama ada pertanyaan berstatus <code>open-blocking</code>. Jawab pertanyaannya di rapat, ubah statusnya menjadi <code>decided</code>, lalu konfirmasi lagi. Analyst tetap bisa mengonfirmasi sendiri lebih dulu.</p><p><strong><code>the questions table has no &quot;Status&quot; column …</code></strong> Header kolom <code>Status</code> di tabel pertanyaan diterjemahkan. Kembalikan ke <code>Status</code>.</p><p><strong><code>rule needing business approval names capability `&lt;x&gt;`, which the proposal does not list</code></strong> Aturan yang ditunjuk memakai capability yang tidak ada di bagian Capabilities. Tambahkan capability-nya atau perbaiki penunjuknya.</p><p><strong><code>business-rules needs business to be ticked as well</code></strong> / <strong><code>business-rules is ticked but no rule needing business approval is listed</code></strong> Gate 2 butuh Gate 1, dan butuh minimal satu aturan yang ditunjuk.</p><p><strong><code>rule needing business approval not found: `&lt;x&gt;` → Requirement: &lt;nama&gt;</code></strong> Saat specs dikonfirmasi, requirement yang ditunjuk proposal tidak ada di spec, atau dihapus/di-rename oleh work ini. Samakan namanya persis dengan header <code>### Requirement:</code>.</p><p><strong><code>proposal lists unknown areas: … (known: …)</code></strong> Ada checkbox di proposal yang kata pertamanya bukan nama area. Area yang dikenal: <code>design</code>, <code>frontend</code>, <code>backend</code>, <code>api</code>, <code>business</code>, <code>business-rules</code>. Checkbox lain tidak boleh ada di proposal.</p><h2 id="saat-membuat-work" tabindex="-1">Saat membuat work <a class="header-anchor" href="#saat-membuat-work" aria-label="Permalink to &quot;Saat membuat work&quot;">​</a></h2><p><strong><code>work name &quot;&lt;nama&gt;&quot; must be kebab-case (lowercase letters, digits and hyphens)</code></strong> Pakai huruf kecil dan tanda hubung, misalnya <code>pemesanan-buku</code>.</p><p><strong><code>no deuz/config.yaml found here or in any parent directory; run </code>deuz init<code> first</code></strong> Jalankan perintah dari dalam repository proyek, jalankan <code>/deuz:init</code>, atau tunjuk root-nya dengan <code>--root</code>.</p><h2 id="saat-validasi-deuz-validate" tabindex="-1">Saat validasi (<code>deuz validate</code>) <a class="header-anchor" href="#saat-validasi-deuz-validate" aria-label="Permalink to &quot;Saat validasi (`deuz validate`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kode</th><th>Arti</th><th>Perbaikan</th></tr></thead><tbody><tr><td><code>status-mismatch</code></td><td><code>.deuz.yaml</code> berbeda dengan kondisi file</td><td>Jalankan <code>deuz status</code> untuk melihat sebabnya. <code>deuz ready</code> atau <code>deuz status --write</code> menulis ulang filenya</td></tr><tr><td><code>spec-merge</code></td><td>Delta tidak cocok dengan spec permanen, misalnya <code>ADDED</code> untuk requirement yang sudah ada, atau <code>MODIFIED</code> untuk yang belum ada</td><td>Pakai operasi yang sesuai. Lihat <a href="./menulis-spec">Menulis spec</a></td></tr><tr><td><code>spec-missing</code></td><td>Capability di proposal belum punya file spec</td><td>Tulis spec-nya, atau hapus capability-nya dari proposal</td></tr><tr><td><code>uncovered-scenario</code></td><td>Scenario belum ada di coverage map <code>tasks-test</code></td><td>Tambahkan barisnya. Status <code>belum ada</code> juga boleh, asal jujur</td></tr><tr><td><code>template-comment</code></td><td>Ada komentar HTML sisa panduan template</td><td>Hapus. Penanda <code>&lt;!-- deuz:… --&gt;</code> tidak termasuk</td></tr><tr><td><code>gate-proposal</code></td><td>Proposal (yang belum <code>ready</code>) melanggar aturan gate</td><td>Sama dengan pesan di bagian konfirmasi di atas</td></tr><tr><td><code>gate-open-question</code></td><td>Ada pertanyaan <code>open-blocking</code> sementara bisnis adalah pemilik</td><td>Jawab dulu sebelum rapat persetujuan</td></tr><tr><td><code>no-hash</code></td><td>Konfirmasi lama tidak menyimpan hash, jadi perubahan setelahnya tidak terdeteksi</td><td>Pemiliknya mengonfirmasi ulang dengan <code>/deuz:ready</code></td></tr></tbody></table><h2 id="saat-archive" tabindex="-1">Saat archive <a class="header-anchor" href="#saat-archive" aria-label="Permalink to &quot;Saat archive&quot;">​</a></h2><p><strong><code>&lt;artifact&gt; is missing</code></strong> atau <strong><code>&lt;artifact&gt; is draft</code></strong> Semua dokumen harus <code>ready</code> atau <code>skipped</code> sebelum archive.</p><p><strong><code>&lt;tasks&gt; has N open task(s)</code></strong> Semua checkbox di setiap tasks yang tidak di-skip harus <code>- [x]</code>. Selesaikan dulu, atau perbarui daftar task bersama pemiliknya (yang berarti konfirmasi ulang).</p><p><strong>Promote manual</strong> Kalau <code>api-contract</code> ada tapi <code>tasks-backend</code> di-skip, tidak ada task yang menerjemahkan kontrak ke definisi API. Pesannya <code>api-contract must be promoted to &lt;home&gt; by hand (its tasks artifact is skipped); …</code>. Kerjakan secara manual, lalu jalankan <code>deuz archive --confirm-promote api-contract</code>.</p><h2 id="lain-lain" tabindex="-1">Lain-lain <a class="header-anchor" href="#lain-lain" aria-label="Permalink to &quot;Lain-lain&quot;">​</a></h2><p><strong>Dokumen yang tidak saya ubah tiba-tiba ditandai <em>recheck</em></strong> Dokumen yang dibutuhkannya berubah setelah dokumen itu dikonfirmasi. Pastikan isinya masih berlaku. Kalau perlu diubah, ubah lalu konfirmasi ulang.</p><p><strong>Skill bilang &quot;hasilnya dihitung agent&quot;</strong> CLI tidak ditemukan. Jalankan <code>make build</code> di folder deuz, atau tambahkan <code>bin/</code> ke <code>PATH</code>.</p><p><strong>Perubahan skill tidak terbaca</strong> Buka sesi Claude Code baru setelah mengubah skill atau aturan.</p>',28)])])}const k=e(o,[["render",i]]);export{m as __pageData,k as default};
